  "source": "def investigate(context, acquire):
    capacity = context['capacity']
    events = context['events']
    order = []
    hits = 0
    misses = 0
    for event in events:
        if event['op'] == 'reset':
            order = []
            hits = 0
            misses = 0
        else:
            key = event['key']
            if key in order:
                hits = hits + 1
                order.remove(key)
                order.append(key)
            else:
                misses = misses + 1
                order.append(key)
                if len(order) > capacity:
                    order.pop(0)
    return {'hits': hits, 'misses': misses, 'size': len(order)}
